-- rowstile 0.1.0-dev: a_column_wins. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', 'a2686adb8083181c', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM 'a2686adb8083181c' THEN
    PERFORM pg_catalog.set_config('authz_migration.read_only', pg_catalog.current_setting('default_transaction_read_only'), false);
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM 'a2686adb8083181c' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only until the migration''s last statement; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = 'a2686adb8083181c' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM '89ecdc3b8f322e68' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      '89ecdc3b8f322e68', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'fm_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

CREATE OR REPLACE FUNCTION authz.uid() RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $uid$
#variable_conflict use_column
BEGIN RETURN (SELECT u."id" FROM "fm"."users" u WHERE u."id" = (CASE WHEN authz_int.session_ok() AND coalesce(pg_catalog.current_setting('authz.principal_type', true), '') IN ('', 'user') AND pg_catalog.pg_input_is_valid(pg_catalog.current_setting('authz.user_id', true), 'uuid') THEN pg_catalog.current_setting('authz.user_id', true)::uuid END)); END
$uid$;

-- Inheritance tables kept whose tables have other tables under them since they were computed (a partition
-- attached or detached: no trigger saw those rows) are computed again
DO $stale$
DECLARE r record;
BEGIN
  IF to_regclass('authz_int.trees') IS NULL THEN RETURN; END IF;
  FOR r IN SELECT n.name, n.oids, n.fn FROM (VALUES ('group__parent__tree', ARRAY[to_regclass('"fm"."groups"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"fm"."groups"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid), 'authz_int."group__parent__tree_rebuild"()'), ('folder__parent__tree', ARRAY[to_regclass('"fm"."folders"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"fm"."folders"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid), 'authz_int."folder__parent__tree_rebuild"()')) n(name, oids, fn)
           JOIN authz_int.trees t ON t.name = n.name
           WHERE t.oids IS DISTINCT FROM n.oids AND to_regprocedure(n.fn) IS NOT NULL LOOP
    EXECUTE format('SELECT %s', r.fn);
    UPDATE authz_int.trees SET oids = r.oids WHERE name = r.name;
  END LOOP;
END $stale$;

-- What else may have changed when objects of a type did: the objects that read them through a relation (a
-- dot, inheritance, a group's members, a group inside a group), then those that read those, until nothing
-- is new. Past 1000 objects of a type: all of them ({*}), and all of what reads them. Each is
-- announced with the cause 'dependent'.
CREATE OR REPLACE FUNCTION authz_int.dependents(p_type text, p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE
  v_all boolean := '*' = ANY (p_ids);
  v_rows bigint; v_most int;
  -- for each type: the ids known (s), new in the last round (n), found in this one (x), how many were found (c),
  -- and whether it is all of them (a)
  s1 bigint[] := '{}'; n1 bigint[] := '{}'; x1 bigint[]; c1 int := 0; a1 boolean := false;  -- file
  s2 bigint[] := '{}'; n2 bigint[] := '{}'; x2 bigint[]; c2 int := 0; a2 boolean := false;  -- folder
  s3 uuid[] := '{}'; n3 uuid[] := '{}'; x3 uuid[]; c3 int := 0; a3 boolean := false;  -- group
  s4 bigint[] := '{}'; n4 bigint[] := '{}'; x4 bigint[]; c4 int := 0; a4 boolean := false;  -- membership
  s5 bigint[] := '{}'; n5 bigint[] := '{}'; x5 bigint[]; c5 int := 0; a5 boolean := false;  -- version
BEGIN
  CASE p_type
    WHEN 'file' THEN
      IF v_all THEN a1 := true;
      ELSE n1 := ARRAY(SELECT DISTINCT x::bigint FROM unnest(p_ids) x WHERE pg_input_is_valid(x, 'bigint')); s1 := n1;
      END IF;
    WHEN 'folder' THEN
      IF v_all THEN a2 := true;
      ELSE n2 := ARRAY(SELECT DISTINCT x::bigint FROM unnest(p_ids) x WHERE pg_input_is_valid(x, 'bigint')); s2 := n2;
      END IF;
    WHEN 'group' THEN
      IF v_all THEN a3 := true;
      ELSE n3 := ARRAY(SELECT DISTINCT x::uuid FROM unnest(p_ids) x WHERE pg_input_is_valid(x, 'uuid')); s3 := n3;
      END IF;
    ELSE RETURN;  -- nothing reads its objects
  END CASE;
  LOOP
    -- all of a type: all of what reads it too
    IF a1 THEN a5 := true; END IF;
    IF a2 THEN a1 := true; a5 := true; END IF;
    IF a3 THEN a1 := true; a2 := true; a4 := true; a5 := true; END IF;
    EXIT WHEN (a1 OR cardinality(n1) = 0) AND (a2 OR cardinality(n2) = 0) AND (a3 OR cardinality(n3) = 0) AND (a4 OR cardinality(n4) = 0) AND (a5 OR cardinality(n5) = 0);
    IF NOT a1 AND (cardinality(n2) > 0 OR cardinality(n3) > 0) THEN
      v_most := cardinality(s1) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (authz__.s1)), '{}')
        INTO v_rows, x1
        FROM (SELECT x."id" FROM "fm"."files" x WHERE x."folder_id" = ANY (authz__.n2) AND cardinality(authz__.n2) > 0
          UNION ALL SELECT g.object_id::bigint FROM authz.shares g WHERE g.subject_type = 'group' AND g.subject_id = ANY (authz__.n3::text[]) AND g.subject_relation = 'member' AND g.object_type = 'file' AND pg_input_is_valid(g.object_id, 'bigint') AND cardinality(authz__.n3) > 0
          LIMIT authz__.v_most) d(v);
      a1 := v_rows >= v_most;
    ELSE
      x1 := '{}';
    END IF;
    IF NOT a2 AND (cardinality(n2) > 0 OR cardinality(n3) > 0) THEN
      v_most := cardinality(s2) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (authz__.s2)), '{}')
        INTO v_rows, x2
        FROM (SELECT x."id" FROM "fm"."folders" x WHERE x."parent_id" = ANY (authz__.n2) AND cardinality(authz__.n2) > 0
          UNION ALL SELECT g.object_id::bigint FROM authz.shares g WHERE g.subject_type = 'group' AND g.subject_id = ANY (authz__.n3::text[]) AND g.subject_relation = 'member' AND g.object_type = 'folder' AND pg_input_is_valid(g.object_id, 'bigint') AND cardinality(authz__.n3) > 0
          LIMIT authz__.v_most) d(v);
      a2 := v_rows >= v_most;
    ELSE
      x2 := '{}';
    END IF;
    IF NOT a3 AND (cardinality(n3) > 0) THEN
      v_most := cardinality(s3) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (authz__.s3)), '{}')
        INTO v_rows, x3
        FROM (SELECT x."id" FROM "fm"."groups" x WHERE x."parent_id" = ANY (authz__.n3) AND cardinality(authz__.n3) > 0
          UNION ALL SELECT x."parent_id" FROM "fm"."groups" x WHERE x."id" = ANY (authz__.n3) AND cardinality(authz__.n3) > 0
          LIMIT authz__.v_most) d(v);
      a3 := v_rows >= v_most;
    ELSE
      x3 := '{}';
    END IF;
    IF NOT a4 AND (cardinality(n3) > 0) THEN
      v_most := cardinality(s4) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (authz__.s4)), '{}')
        INTO v_rows, x4
        FROM (SELECT x."id" FROM "fm"."group_members" x WHERE x."group_id" = ANY (authz__.n3) AND cardinality(authz__.n3) > 0
          LIMIT authz__.v_most) d(v);
      a4 := v_rows >= v_most;
    ELSE
      x4 := '{}';
    END IF;
    IF NOT a5 AND (cardinality(n1) > 0) THEN
      v_most := cardinality(s5) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (authz__.s5)), '{}')
        INTO v_rows, x5
        FROM (SELECT x."id" FROM "fm"."file_versions" x WHERE x."file_id" = ANY (authz__.n1) AND cardinality(authz__.n1) > 0
          LIMIT authz__.v_most) d(v);
      a5 := v_rows >= v_most;
    ELSE
      x5 := '{}';
    END IF;
    n1 := x1; s1 := s1 || x1; c1 := c1 + cardinality(x1); a1 := a1 OR c1 > 1000;
    n2 := x2; s2 := s2 || x2; c2 := c2 + cardinality(x2); a2 := a2 OR c2 > 1000;
    n3 := x3; s3 := s3 || x3; c3 := c3 + cardinality(x3); a3 := a3 OR c3 > 1000;
    n4 := x4; s4 := s4 || x4; c4 := c4 + cardinality(x4); a4 := a4 OR c4 > 1000;
    n5 := x5; s5 := s5 || x5; c5 := c5 + cardinality(x5); a5 := a5 OR c5 > 1000;
  END LOOP;
  IF a1 AND NOT (v_all AND p_type = 'file') THEN
    PERFORM authz_int.announce('file', '{*}', 'dependent', false);
  ELSIF NOT a1 AND c1 > 0 THEN
    PERFORM authz_int.announce('file', ARRAY(SELECT v::text FROM unnest(s1[cardinality(s1) - c1 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
  IF a2 AND NOT (v_all AND p_type = 'folder') THEN
    PERFORM authz_int.announce('folder', '{*}', 'dependent', false);
  ELSIF NOT a2 AND c2 > 0 THEN
    PERFORM authz_int.announce('folder', ARRAY(SELECT v::text FROM unnest(s2[cardinality(s2) - c2 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
  IF a3 AND NOT (v_all AND p_type = 'group') THEN
    PERFORM authz_int.announce('group', '{*}', 'dependent', false);
  ELSIF NOT a3 AND c3 > 0 THEN
    PERFORM authz_int.announce('group', ARRAY(SELECT v::text FROM unnest(s3[cardinality(s3) - c3 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
  IF a4 AND NOT (v_all AND p_type = 'membership') THEN
    PERFORM authz_int.announce('membership', '{*}', 'dependent', false);
  ELSIF NOT a4 AND c4 > 0 THEN
    PERFORM authz_int.announce('membership', ARRAY(SELECT v::text FROM unnest(s4[cardinality(s4) - c4 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
  IF a5 AND NOT (v_all AND p_type = 'version') THEN
    PERFORM authz_int.announce('version', '{*}', 'dependent', false);
  ELSIF NOT a5 AND c5 > 0 THEN
    PERFORM authz_int.announce('version', ARRAY(SELECT v::text FROM unnest(s5[cardinality(s5) - c5 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
END $f$;

-- a role that gives more or less: the objects it is given on (its assignments are shares, 'role:<id>'; a change:
-- the roles it was in and is in)
CREATE OR REPLACE FUNCTION authz_int.on_role_permissions() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
BEGIN
  IF TG_OP = 'UPDATE' THEN
    PERFORM authz_int.changed(g.object_type, array_agg(DISTINCT g.object_id), 'role')
    FROM authz.shares g WHERE g.relation IN (SELECT 'role:' || r.role_id FROM role_rows r
                                             UNION SELECT 'role:' || n.role_id FROM new_role_rows n) GROUP BY g.object_type;
  ELSE
    PERFORM authz_int.changed(g.object_type, array_agg(DISTINCT g.object_id), 'role')
    FROM authz.shares g WHERE g.relation IN (SELECT 'role:' || r.role_id FROM role_rows r) GROUP BY g.object_type;
  END IF;
  RETURN NULL;
END $f$;

-- 'shared if {...}' conditions (they run as the policy's owner, like permissions). A bare name in one is
-- a column of what the condition reads, never a parameter of this function
CREATE OR REPLACE FUNCTION authz_int.share_if(p_key text, p_object_id text, p_subject_type text, p_subject_id text,
  p_subject_relation text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
  CASE p_key
    WHEN NULL THEN NULL;
    ELSE RETURN true;
  END CASE;
END $f$;

-- deleting a role removes its assignments
CREATE OR REPLACE FUNCTION authz_int.role_gone() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
BEGIN
  DELETE FROM authz.shares WHERE relation IN (SELECT 'role:' || o.id FROM old_rows o);
  RETURN NULL;
END $f$;

-- after a change to the links of p_ids alone (nothing inserted, deleted or renumbered), everything
-- below them (p_below, which includes them) keeps its stored rows among itself, and only rows to the
-- ancestors of p_ids, before or after, can change: to those, each row below now reaches whatever the
-- stored rows of the links leaving the part below lead to. A move of a folder with thousands below it
-- then rewrites (below it) x (its old and new ancestors) rows instead of recomputing every one. That
-- holds only if no link of p_ids, before or after, leads back into the part below them (checked here;
-- false means nothing was done and the caller recomputes). Plans are made for each call's arrays:
-- one made for a few rows would be ruinous for a big move
CREATE OR REPLACE FUNCTION authz_int."group__parent__tree_shift"(p_ids uuid[], p_below uuid[]) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_custom_plan AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE touched uuid[];
BEGIN
  IF EXISTS (SELECT 1 FROM authz_int."group__parent__tree" t JOIN unnest($2) b(id) ON b.id = t.ancestor
             WHERE t.descendant = ANY ($1) AND t.ancestor <> t.descendant) THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM unnest($1) b(_y) JOIN "fm"."groups" c ON c."id" = b._y
             CROSS JOIN LATERAL (
               (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
             WHERE (e._link = 0) AND e._parent = ANY ($2)) THEN
    RETURN false;
  END IF;
  -- the ancestors of p_ids before (stored) and after (through their links now): no others change
  touched := ARRAY(
    SELECT t.ancestor FROM authz_int."group__parent__tree" t WHERE t.descendant = ANY ($1) AND t.ancestor <> t.descendant
    UNION
    SELECT u.ancestor FROM unnest($1) b(_y) JOIN "fm"."groups" c ON c."id" = b._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
    JOIN authz_int."group__parent__tree" u ON u.descendant = e._parent
    WHERE (e._link = 0));
  WITH below AS MATERIALIZED (SELECT x AS _y FROM unnest($2) x),
  -- links from the part below to outside it, as they are now
  exits AS MATERIALIZED (
    SELECT e._child AS y, e._parent AS p
    FROM below JOIN "fm"."groups" c ON c."id" = below._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = below._y OFFSET 0)) e
    WHERE (e._link = 0)),
  -- each row below: the touched ancestors it now reaches, through the exits it reaches
  fresh AS MATERIALIZED (
    SELECT DISTINCT d.descendant AS d, u.ancestor AS a
    FROM exits
    JOIN authz_int."group__parent__tree" u ON u.descendant = exits.p AND u.ancestor = ANY (authz__.touched)
    JOIN authz_int."group__parent__tree" d ON d.ancestor = exits.y
    WHERE NOT EXISTS (SELECT 1 FROM below b WHERE b._y = exits.p)),
  stale AS (
    DELETE FROM authz_int."group__parent__tree" t
    WHERE t.ancestor = ANY (authz__.touched) AND t.descendant IN (SELECT _y FROM below)
      AND NOT EXISTS (SELECT 1 FROM fresh o WHERE o.d = t.descendant AND o.a = t.ancestor))
  INSERT INTO authz_int."group__parent__tree" (descendant, ancestor) SELECT d, a FROM fresh ON CONFLICT DO NOTHING;
  RETURN true;
END $f$;

-- recompute the given rows and everything linked below them; p_shift: only their own links changed
CREATE OR REPLACE FUNCTION authz_int."group__parent__tree_refresh"(p_ids uuid[], p_shift boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE affected uuid[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('group');
  WITH RECURSIVE down(id) AS (
    SELECT x FROM unnest($1) AS x WHERE x IS NOT NULL
    UNION
    SELECT e._child FROM down CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)) e)
  SELECT array_agg(id) INTO affected FROM down;
  IF NOT (p_shift AND authz_int."group__parent__tree_shift"(p_ids, affected)) THEN
    DELETE FROM authz_int."group__parent__tree" WHERE descendant = ANY (affected);
    INSERT INTO authz_int."group__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."group__parent__tree_compute"(affected);
  END IF;
  PERFORM authz_int.changed('group', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE), 10000 rows at a time
CREATE OR REPLACE FUNCTION authz_int."group__parent__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE batch uuid[];
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('group');
  DELETE FROM authz_int."group__parent__tree";
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "fm"."groups") k GROUP BY (k.n - 1) / 10000 LOOP
    INSERT INTO authz_int."group__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."group__parent__tree_compute"(batch);
  END LOOP;
END $f$;

-- what a rebuild would give against what is stored, 10000 rows at a time; then nothing stored for a row
-- that is gone
CREATE OR REPLACE FUNCTION authz_int."group__parent__tree_verify"() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE batch uuid[];
BEGIN
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "fm"."groups") k GROUP BY (k.n - 1) / 10000 LOOP
    IF EXISTS (WITH fresh AS MATERIALIZED (SELECT o_descendant AS d, o_ancestor AS a FROM authz_int."group__parent__tree_compute"(batch)),
                    stored AS MATERIALIZED (SELECT descendant AS d, ancestor AS a FROM authz_int."group__parent__tree"
                                            WHERE descendant = ANY (batch))
               (SELECT d, a FROM fresh EXCEPT SELECT d, a FROM stored)
               UNION ALL
               (SELECT d, a FROM stored EXCEPT SELECT d, a FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM authz_int."group__parent__tree" s
             WHERE NOT EXISTS (SELECT 1 FROM "fm"."groups" x WHERE x."id" = s.descendant)) THEN
    RETURN false;
  END IF;
  RETURN true;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."group__parent__tree_check_loops"(p_ids uuid[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE bad text;
BEGIN
  WITH RECURSIVE up(start, id) AS (
    SELECT e._child, e._parent FROM authz_int."group__parent__tree_parents" e WHERE e._child = ANY ($1)
    UNION
    SELECT up.start, e._parent FROM up CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT r."id" AS _child, r."parent_id" AS _parent FROM "fm"."groups" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = up.id OFFSET 0)) e)
  SELECT start::text INTO bad FROM up WHERE id = start LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'group % cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowstile help AZ713';
  END IF;
END $f$;

-- rows inserted, deleted, moved, or whose id or conditions change
CREATE OR REPLACE FUNCTION authz_int."group__parent__tree_on_rows"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE ids uuid[]; shift boolean := false;
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."id" FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    -- rows whose id changed: the old id disappears and the new one appears
    ids := ARRAY(
      SELECT o."id" FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id" = o."id")
      UNION SELECT n."id" FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id" = n."id"));
    shift := cardinality(ids) = 0;
    ids := ARRAY(
      SELECT n."id" FROM new_rows n JOIN old_rows o ON o."id" = n."id"
      WHERE n."parent_id" IS DISTINCT FROM o."parent_id"
      UNION SELECT unnest(authz__.ids));
  ELSE
    ids := ARRAY(SELECT o."id" FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('group');
  IF TG_OP <> 'DELETE' THEN PERFORM authz_int."group__parent__tree_check_loops"(ids); END IF;
    PERFORM authz_int."group__parent__tree_refresh"(ids, shift);
  END IF;
  RETURN NULL;
END $f$;

-- after a change to the links of p_ids alone (nothing inserted, deleted or renumbered), everything
-- below them (p_below, which includes them) keeps its stored rows among itself, and only rows to the
-- ancestors of p_ids, before or after, can change: to those, each row below now reaches whatever the
-- stored rows of the links leaving the part below lead to. A move of a folder with thousands below it
-- then rewrites (below it) x (its old and new ancestors) rows instead of recomputing every one. That
-- holds only if no link of p_ids, before or after, leads back into the part below them (checked here;
-- false means nothing was done and the caller recomputes). Plans are made for each call's arrays:
-- one made for a few rows would be ruinous for a big move
CREATE OR REPLACE FUNCTION authz_int."folder__parent__tree_shift"(p_ids bigint[], p_below bigint[]) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET plan_cache_mode = force_custom_plan AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE touched bigint[];
BEGIN
  IF EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" t JOIN unnest($2) b(id) ON b.id = t.ancestor
             WHERE t.descendant = ANY ($1) AND t.ancestor <> t.descendant) THEN
    RETURN false;
  END IF;
  IF EXISTS (SELECT 1 FROM unnest($1) b(_y) JOIN "fm"."folders" c ON c."id" = b._y
             CROSS JOIN LATERAL (
               (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
             WHERE ((e._link = 0 AND coalesce((inherit), false))) AND e._parent = ANY ($2)) THEN
    RETURN false;
  END IF;
  -- the ancestors of p_ids before (stored) and after (through their links now): no others change
  touched := ARRAY(
    SELECT t.ancestor FROM authz_int."folder__parent__tree" t WHERE t.descendant = ANY ($1) AND t.ancestor <> t.descendant
    UNION
    SELECT u.ancestor FROM unnest($1) b(_y) JOIN "fm"."folders" c ON c."id" = b._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = b._y OFFSET 0)) e
    JOIN authz_int."folder__parent__tree" u ON u.descendant = e._parent
    WHERE ((e._link = 0 AND coalesce((inherit), false))));
  WITH below AS MATERIALIZED (SELECT x AS _y FROM unnest($2) x),
  -- links from the part below to outside it, as they are now
  exits AS MATERIALIZED (
    SELECT e._child AS y, e._parent AS p
    FROM below JOIN "fm"."folders" c ON c."id" = below._y
    CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._child = below._y OFFSET 0)) e
    WHERE ((e._link = 0 AND coalesce((inherit), false)))),
  -- each row below: the touched ancestors it now reaches, through the exits it reaches
  fresh AS MATERIALIZED (
    SELECT DISTINCT d.descendant AS d, u.ancestor AS a
    FROM exits
    JOIN authz_int."folder__parent__tree" u ON u.descendant = exits.p AND u.ancestor = ANY (authz__.touched)
    JOIN authz_int."folder__parent__tree" d ON d.ancestor = exits.y
    WHERE NOT EXISTS (SELECT 1 FROM below b WHERE b._y = exits.p)),
  stale AS (
    DELETE FROM authz_int."folder__parent__tree" t
    WHERE t.ancestor = ANY (authz__.touched) AND t.descendant IN (SELECT _y FROM below)
      AND NOT EXISTS (SELECT 1 FROM fresh o WHERE o.d = t.descendant AND o.a = t.ancestor))
  INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor) SELECT d, a FROM fresh ON CONFLICT DO NOTHING;
  RETURN true;
END $f$;

-- recompute the given rows and everything linked below them; p_shift: only their own links changed
CREATE OR REPLACE FUNCTION authz_int."folder__parent__tree_refresh"(p_ids bigint[], p_shift boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE affected bigint[];
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  WITH RECURSIVE down(id) AS (
    SELECT x FROM unnest($1) AS x WHERE x IS NOT NULL
    UNION
    SELECT e._child FROM down CROSS JOIN LATERAL (
      (SELECT x.* FROM (SELECT 0 AS _link, r."id" AS _child, r."parent_id" AS _parent FROM "fm"."folders" r WHERE r."parent_id" IS NOT NULL) x WHERE x._parent = down.id OFFSET 0)) e)
  SELECT array_agg(id) INTO affected FROM down;
  IF NOT (p_shift AND authz_int."folder__parent__tree_shift"(p_ids, affected)) THEN
    DELETE FROM authz_int."folder__parent__tree" WHERE descendant = ANY (affected);
    INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."folder__parent__tree_compute"(affected);
  END IF;
  PERFORM authz_int.changed('folder', affected::text[], 'inheritance');
END $f$;

-- recompute everything (backfill, TRUNCATE), 10000 rows at a time
CREATE OR REPLACE FUNCTION authz_int."folder__parent__tree_rebuild"() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE batch bigint[];
BEGIN
  UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder');
  DELETE FROM authz_int."folder__parent__tree";
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "fm"."folders") k GROUP BY (k.n - 1) / 10000 LOOP
    INSERT INTO authz_int."folder__parent__tree" (descendant, ancestor)
    SELECT o_descendant, o_ancestor FROM authz_int."folder__parent__tree_compute"(batch);
  END LOOP;
END $f$;

-- what a rebuild would give against what is stored, 10000 rows at a time; then nothing stored for a row
-- that is gone
CREATE OR REPLACE FUNCTION authz_int."folder__parent__tree_verify"() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE batch bigint[];
BEGIN
  FOR batch IN SELECT array_agg(k.k) FROM (SELECT "id" AS k, row_number() OVER () AS n FROM "fm"."folders") k GROUP BY (k.n - 1) / 10000 LOOP
    IF EXISTS (WITH fresh AS MATERIALIZED (SELECT o_descendant AS d, o_ancestor AS a FROM authz_int."folder__parent__tree_compute"(batch)),
                    stored AS MATERIALIZED (SELECT descendant AS d, ancestor AS a FROM authz_int."folder__parent__tree"
                                            WHERE descendant = ANY (batch))
               (SELECT d, a FROM fresh EXCEPT SELECT d, a FROM stored)
               UNION ALL
               (SELECT d, a FROM stored EXCEPT SELECT d, a FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" s
             WHERE NOT EXISTS (SELECT 1 FROM "fm"."folders" x WHERE x."id" = s.descendant)) THEN
    RETURN false;
  END IF;
  RETURN true;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."folder__parent__tree_check_loops"(p_ids bigint[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
