CREATE OR REPLACE FUNCTION authz_int."file__col_audit_ins"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
BEGIN
    PERFORM authz_int.changed('file', ARRAY(SELECT n."id"::text FROM new_rows n), 'insert');
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."file__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
BEGIN
    -- any column may change access: a condition reads the whole row, or the app's code
    PERFORM authz_int.changed('file', ARRAY(SELECT n."id"::text FROM new_rows n UNION SELECT o."id"::text FROM old_rows o), 'update');
    -- a partitioned table: the rows this update put in another partition, which the row trigger never sees
    IF (SELECT relkind FROM pg_class WHERE oid = TG_RELID) = 'p' THEN
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'file', n."id"::text, 'folder', n."folder_id"::text, jsonb_build_object('column', 'folder_id', 'was', o."folder_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."folder_id" IS DISTINCT FROM o."folder_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'file'
          AND a.object_id = n."id"::text AND a.relation = 'folder' AND a.detail->>'column' = 'folder_id'
          AND a.subject_id IS NOT DISTINCT FROM n."folder_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."folder_id"));
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'file', n."id"::text, 'owner', n."owner_id"::text, jsonb_build_object('column', 'owner_id', 'was', o."owner_id"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."owner_id" IS DISTINCT FROM o."owner_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'file'
          AND a.object_id = n."id"::text AND a.relation = 'owner' AND a.detail->>'column' = 'owner_id'
          AND a.subject_id IS NOT DISTINCT FROM n."owner_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."owner_id"));
    END IF;
  RETURN NULL;
END $f$;

