-- fm.folders: no row has the id, or the user may select it (what the rules' explanations answer for)
CREATE OR REPLACE FUNCTION authz_int."fm.folders:seen"(p_id bigint) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
  RETURN NOT EXISTS (SELECT 1 FROM "fm"."folders" o WHERE o."id" = $1)
      OR EXISTS (SELECT 1 FROM "fm"."folders" "folders" WHERE "folders"."id" = $1
        AND (SELECT authz_int.scope_cmd('fm.folders', 'select')) AND (coalesce("folders"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__editor" v WHERE v.id = "folders"."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = "folders"."id")
    OR (coalesce((inherit), false)
    AND authz_int."folder__view__has"("folders"."parent_id"))));
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."fm.folders:update:why"(p_row "fm"."folders", p_stored boolean) RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE v boolean[] := authz_gen."fm.folders:update:items"(p_row, current_user); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update : edit  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule fm.folders update'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT CASE WHEN coalesce(pg_catalog.current_setting('authz.acting_user', true), '') <> ''
    THEN '  no   the session views as someone else: it may not update on fm.folders'
    ELSE '  no   the sign-in''s scopes do not allow update on fm.folders' END; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'edit';
  IF NOT v[4] AND p_stored THEN
    RETURN QUERY SELECT '    ' || l FROM authz.explain('folder', ((p_row)."id"::text), 'edit') l LIMIT 20;
  END IF;
END $f$;

