DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."version__edit");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'version.edit = file.edit';
  BEGIN
    v_ok := ($1) IN (SELECT id FROM authz_int."version__file__edit");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'file.edit';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."file_id" AS id FROM "fm"."file_versions" r WHERE r."id" = $1 AND r."file_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'file', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'file is a file you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'file is file '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has edit' ELSE ', without edit' END;
      IF NOT ('file:edit:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."file__edit__why"(v_t.id::bigint, p_depth + 1 + 1, p_seen || ('file:edit:' || v_t.id), p_asker);
      END IF;
    END LOOP;
  END;
END $f$;

-- May the signed-in user see this object (select it)? A hidden object reads as a missing one
CREATE OR REPLACE FUNCTION authz_int.visible(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
  IF NOT coalesce(pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)), false) THEN
    RETURN false;
  END IF;
  CASE p_type
    WHEN 'user' THEN
      RETURN EXISTS (SELECT 1 FROM "fm"."users" "users" WHERE "users"."id" = $2::uuid
        AND true);
    WHEN 'group' THEN
      RETURN EXISTS (SELECT 1 FROM "fm"."groups" "groups" WHERE "groups"."id" = $2::uuid
        AND (SELECT authz_int.scope_cmd('fm.groups', 'select')) AND coalesce(((SELECT authz.uid()) IS NOT NULL), false));
    WHEN 'membership' THEN
      RETURN EXISTS (SELECT 1 FROM "fm"."group_members" "group_members" WHERE "group_members"."id" = $2::bigint
        AND (SELECT authz_int.scope_cmd('fm.group_members', 'select')) AND coalesce(((SELECT authz.uid()) IS NOT NULL), false));
    WHEN 'folder' THEN
      RETURN EXISTS (SELECT 1 FROM "fm"."folders" "folders" WHERE "folders"."id" = $2::bigint
        AND (SELECT authz_int.scope_cmd('fm.folders', 'select')) AND (coalesce("folders"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__editor" v WHERE v.id = "folders"."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = "folders"."id")
    OR (coalesce((inherit), false)
    AND authz_int."folder__view__has"("folders"."parent_id"))));
    WHEN 'file' THEN
      RETURN EXISTS (SELECT 1 FROM "fm"."files" "files" WHERE "files"."id" = $2::bigint
        AND (SELECT authz_int.scope_cmd('fm.files', 'select')) AND (coalesce("files"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__editor" v WHERE v.id = "files"."id")
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = "files"."id")
    OR authz_int."folder__view__has"("files"."folder_id")));
    WHEN 'version' THEN
      RETURN EXISTS (SELECT 1 FROM "fm"."file_versions" "file_versions" WHERE "file_versions"."id" = $2::bigint
        AND (SELECT authz_int.scope_cmd('fm.file_versions', 'select')) AND EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = "file_versions"."file_id"));
    ELSE RETURN false;
  END CASE;
END $f$;

-- Everyone who holds a permission on an object: SELECT * FROM authz.who('folder', 3, 'view')
-- Candidates come from the data (a superset); each is checked as that user (the permission itself, authz_int.can).
CREATE OR REPLACE FUNCTION authz.who(p_type text, p_id text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_c text;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_bigint bigint; v_uuid uuid;
BEGIN
  IF NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm) THEN
    RAISE EXCEPTION 'you cannot see who has access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- (the caller's settings are put back below; an error needs nothing put back: Postgres undoes these settings with
  -- the transaction, or the savepoint the error is caught at, as for explain, check_invariants and the logins)
  PERFORM set_config('authz.scopes', '', true);   -- each candidate is checked with full rights
  PERFORM set_config('authz.principal_type', '', true);   -- candidates are users
  <<asking>> BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'group' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'manage' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."group__manage__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "fm"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'membership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'manage' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."membership__manage__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "fm"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'folder' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."folder__share__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "fm"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."folder__edit__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "fm"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."folder__view__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "fm"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'break_glass' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."folder__break_glass__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "fm"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'file' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."file__share__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "fm"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."file__edit__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "fm"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."file__view__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "fm"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'version' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."version__view__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "fm"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."version__edit__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "fm"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- Invariants: checked as everyone who can sign in (named as the audit trail names them: '42', 'user:a:b',
-- 'service:3') and as nobody; returns the violations
CREATE OR REPLACE FUNCTION authz.check_invariants() RETURNS TABLE (invariant text, user_id text, object_ids text[])
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_p text; v_u text; v_ids text[];
BEGIN
  PERFORM set_config('authz.scopes', '', true);
  FOR v_p, v_u IN SELECT '', '' UNION ALL SELECT '', x."id"::text FROM "fm"."users" x LOOP
    PERFORM set_config('authz.principal_type', v_p, true);
    PERFORM set_config('authz.user_id', v_u, true);
    PERFORM authz_int.sign();
    NULL;
  END LOOP;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- Replace a group's members with the list your identity provider sends (administrators, sync jobs):
-- SELECT * FROM authz.sync_members('team', '10', 'member', ARRAY['1', '2'])
CREATE OR REPLACE FUNCTION authz.sync_members(p_type text, p_id text, p_relation text, p_members text[],
  OUT added int, OUT removed int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
BEGIN
  -- NULL is no list: it would remove every member (a sync job's failed fetch, a missing field)
  IF p_members IS NULL OR EXISTS (SELECT 1 FROM unnest(p_members) x WHERE x IS NULL) THEN
    RAISE EXCEPTION 'say who the members are: a list of ids with no NULL in it (an empty list for none)'
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  CASE p_type || '.' || p_relation
    WHEN 'group.member' THEN
      WITH want AS (SELECT DISTINCT x::uuid AS m FROM unnest($4) x),
      del AS (DELETE FROM "fm"."group_members" s WHERE s."group_id" = $2::uuid AND s."user_id" NOT IN (SELECT m FROM want) RETURNING 1),
      ins AS (INSERT INTO "fm"."group_members" ("group_id", "user_id") SELECT $2::uuid, w.m FROM want w
              WHERE NOT EXISTS (SELECT 1 FROM "fm"."group_members" s WHERE s."group_id" = $2::uuid AND s."user_id" = w.m) RETURNING 1)
      SELECT (SELECT count(*) FROM ins)::int, (SELECT count(*) FROM del)::int INTO added, removed;
    ELSE RAISE EXCEPTION '%.% has no single table of members to sync (it needs one source: table(group -> user), without where)',
      p_type, p_relation USING HINT = 'rowstile help AZ707';
  END CASE;
  PERFORM authz_int.audit('sync_members', p_type, authz_int.canon(p_type, p_id), p_relation, 'user', NULL, NULL,
                          jsonb_build_object('added', added, 'removed', removed, 'members', p_members));
END $f$;

-- the API keys of user rows that are gone, or whose id changed, are deleted (authz_int.keys_gone)
CREATE OR REPLACE FUNCTION authz_int."user__keys_gone"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    IF NOT EXISTS (SELECT 1 FROM "fm"."users") THEN   -- the table is empty, and so are those under it
      PERFORM authz_int.keys_gone('user', NULL);
    ELSE   -- TRUNCATE ONLY, or of a table under it: the rows still there keep their keys
      PERFORM authz_int.keys_gone('user', ARRAY(SELECT k.user_id FROM authz.api_keys k WHERE k.principal_type = 'user'
                                                AND NOT EXISTS (SELECT 1 FROM "fm"."users" x WHERE x."id"::text = k.user_id)));
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

-- The partitions of each table with rules and the tables that inherit from one: row-level security on, with
-- no policies of their own, so they are read and written through it only (read directly, they would skip its rules
-- and triggers). Every apply and every migration: one made or attached since is closed too (it alone is locked,
-- as CHILD_TRIGGERS locks only one that lacks the triggers)
DO $rls$
DECLARE c regclass;
BEGIN
  FOR c IN WITH RECURSIVE d(oid) AS (
             SELECT i.inhrelid FROM pg_catalog.pg_inherits i
             WHERE i.inhparent = ANY (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"fm"."file_versions"', '"fm"."files"', '"fm"."folders"', '"fm"."group_members"', '"fm"."groups"']::text[]) x)
             UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass FROM d JOIN pg_catalog.pg_class k ON k.oid = d.oid WHERE NOT k.relrowsecurity LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', c);
  END LOOP;
END $rls$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"fm_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"fm_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."file__edit"', 'authz_int."file__editor"', 'authz_int."file__view"', 'authz_int."file__viewer"', 'authz_int."folder__editor"', 'authz_int."folder__share__direct"', 'authz_int."folder__view"', 'authz_int."folder__viewer"', 'authz_int."group__admin"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"fm_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"fm_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"fm.file_versions:column id, file_id, object_key, creat_edb04104"', '"fm.file_versions:column id, file_id, object_key, created_by:why"', '"fm.file_versions:delete:items"', '"fm.file_versions:delete:why"', '"fm.file_versions:insert:items"', '"fm.file_versions:insert:refuse"', '"fm.file_versions:insert:why"', '"fm.file_versions:rules:explain"', '"fm.file_versions:update:items"', '"fm.file_versions:update:refuse"', '"fm.file_versions:update:why"', '"fm.files:column folder_id after:items"', '"fm.files:column folder_id after:why"', '"fm.files:column id, owner_id:items"', '"fm.files:column id, owner_id:why"', '"fm.files:column object_key after:items"', '"fm.files:column object_key after:why"', '"fm.files:delete:items"', '"fm.files:delete:why"', '"fm.files:insert:items"', '"fm.files:insert:refuse"', '"fm.files:insert:why"', '"fm.files:rules:explain"', '"fm.files:update:items"', '"fm.files:update:refuse"', '"fm.files:update:why"', '"fm.folders:column id, owner_id, inherit:items"', '"fm.folders:column id, owner_id, inherit:why"', '"fm.folders:column parent_id after:items"', '"fm.folders:column parent_id after:why"', '"fm.folders:column parent_id:items"', '"fm.folders:column parent_id:why"', '"fm.folders:delete:items"', '"fm.folders:delete:why"', '"fm.folders:insert:items"', '"fm.folders:insert:refuse"', '"fm.folders:insert:why"', '"fm.folders:rules:explain"', '"fm.folders:update:items"', '"fm.folders:update:refuse"', '"fm.folders:update:why"', '"fm.group_members:column group_id after:items"', '"fm.group_members:column group_id after:why"', '"fm.group_members:column id, user_id:items"', '"fm.group_members:column id, user_id:why"', '"fm.group_members:delete:items"', '"fm.group_members:delete:why"', '"fm.group_members:insert:items"', '"fm.group_members:insert:refuse"', '"fm.group_members:insert:why"', '"fm.group_members:rules:explain"', '"fm.group_members:update:items"', '"fm.group_members:update:refuse"